import re
for name in ["lib.fsi","lib.fss"]:
    path="/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/"+name
    trait=[];fn=[]
    for i,line in enumerate(open(path,encoding="utf-8"),1):
        s=line.strip()
        if s.startswith("(*") : continue
        # find static param lists
        for m in re.finditer(r"\[\\(.*?)\\\]", line):
            body=m.group(1)
            # split params at top-level commas is hard; look for "X extends ... X"
            for pm in re.finditer(r"\b([A-Z]\w*)\s+extends\s+(\{[^}]*\}|[^,\]]+)", body):
                X=pm.group(1); bd=pm.group(2)
                if re.search(r"\[\\\s*"+re.escape(X)+r"\s*\\\]", bd) or re.search(r"\b"+re.escape(X)+r"\b", re.sub(r"\b"+re.escape(X)+r"\s+extends","",bd)):
                    kind = "trait/object" if re.match(r"\s*(value\s+)?(trait|object)\b", line) else "function/opr"
                    (trait if kind=="trait/object" else fn).append((i, s[:110]))
                break
    print("=====",name,"traits/objects:",len(trait),"functions/oprs:",len(fn))
    for i,s in trait: print("  T",i,s)
    for i,s in fn: print("  F",i,s)
EOF

